CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS collections (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), org_id TEXT, owner_user_id TEXT NOT NULL, agent_run_id TEXT UNIQUE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('knowledge','scratch')), home TEXT NOT NULL CHECK(home IN('desktop-only','synced')), encryption TEXT NOT NULL DEFAULT 'org-readable' CHECK(encryption='org-readable'), encrypted_data_key JSONB NOT NULL, dedup_key_ciphertext JSONB NOT NULL, retention_policy JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS collection_acl (collection_id UUID NOT NULL REFERENCES collections(id) ON DELETE CASCADE, principal_type TEXT NOT NULL CHECK(principal_type IN('user','group')), principal_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('view','use-by-agents','edit','manage')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(collection_id,principal_type,principal_id));
CREATE TABLE IF NOT EXISTS manifests (hash TEXT PRIMARY KEY, chunk_ids JSONB NOT NULL, total_size BIGINT NOT NULL CHECK(total_size>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS chunks (collection_id UUID NOT NULL REFERENCES collections(id) ON DELETE CASCADE,id TEXT NOT NULL,size INTEGER NOT NULL CHECK(size>=0),stored_size INTEGER NOT NULL CHECK(stored_size>=0),location TEXT NOT NULL,refcount BIGINT NOT NULL DEFAULT 0 CHECK(refcount>=0),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(collection_id,id));
CREATE TABLE IF NOT EXISTS files (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),collection_id UUID NOT NULL REFERENCES collections(id),path TEXT NOT NULL,current_version_id UUID,deleted_at TIMESTAMPTZ,expires_at TIMESTAMPTZ,created_by_type TEXT NOT NULL CHECK(created_by_type IN('user','agent-run')),created_by_id TEXT NOT NULL,mime TEXT NOT NULL DEFAULT 'application/octet-stream',size BIGINT NOT NULL DEFAULT 0,search_text TEXT,search_vector TSVECTOR GENERATED ALWAYS AS(to_tsvector('simple',coalesce(path,'')||' '||coalesce(search_text,''))) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(collection_id,path));
CREATE TABLE IF NOT EXISTS file_versions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),file_id UUID NOT NULL REFERENCES files(id) ON DELETE CASCADE,chunk_collection_id UUID NOT NULL REFERENCES collections(id),parent_version_id UUID REFERENCES file_versions(id),manifest_hash TEXT REFERENCES manifests(hash),size BIGINT NOT NULL CHECK(size>=0),deleted BOOLEAN NOT NULL DEFAULT FALSE,created_by_type TEXT NOT NULL CHECK(created_by_type IN('user','agent-run')),created_by_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),message TEXT,device_id TEXT NOT NULL,base_server_version_id UUID);
ALTER TABLE files DROP CONSTRAINT IF EXISTS files_current_version_id_fkey; ALTER TABLE files ADD CONSTRAINT files_current_version_id_fkey FOREIGN KEY(current_version_id) REFERENCES file_versions(id);
CREATE TABLE IF NOT EXISTS journal(seq BIGSERIAL PRIMARY KEY,collection_id UUID NOT NULL REFERENCES collections(id),file_id UUID NOT NULL REFERENCES files(id),version_id UUID NOT NULL REFERENCES file_versions(id),op TEXT NOT NULL CHECK(op IN('put','restore','delete','promote','conflict')),at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS edges(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),src_type TEXT NOT NULL,src_id TEXT NOT NULL,dst_type TEXT NOT NULL,dst_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN('links_to','created_by','derived_from')),props JSONB NOT NULL DEFAULT '{}'::jsonb,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(src_type,src_id,dst_type,dst_id,kind));
CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,who_type TEXT NOT NULL,who_id TEXT NOT NULL,device_or_run_id TEXT,file_id UUID REFERENCES files(id),version_id UUID REFERENCES file_versions(id),action TEXT NOT NULL,at TIMESTAMPTZ NOT NULL DEFAULT NOW(),details JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS file_sync_cursors(collection_id UUID NOT NULL REFERENCES collections(id) ON DELETE CASCADE,device_id TEXT NOT NULL,last_seq BIGINT NOT NULL DEFAULT 0,last_push_seq BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(collection_id,device_id));
CREATE INDEX IF NOT EXISTS idx_files_collection_path ON files(collection_id,path);
CREATE INDEX IF NOT EXISTS idx_files_scratch_expiry ON files(expires_at) WHERE expires_at IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_files_search ON files USING GIN(search_vector);
CREATE INDEX IF NOT EXISTS idx_versions_file_created ON file_versions(file_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_journal_collection_seq ON journal(collection_id,seq);
